SET NAMES utf8mb4;
SET time_zone = '+03:00';
CREATE TABLE IF NOT EXISTS users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(64) NOT NULL UNIQUE,role ENUM('admin','user') NOT NULL DEFAULT 'user',password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS login_attempts (attempt_key CHAR(64) PRIMARY KEY,attempt_count SMALLINT UNSIGNED NOT NULL DEFAULT 0,first_attempt INT UNSIGNED NOT NULL,locked_until INT UNSIGNED NOT NULL DEFAULT 0,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS settings (setting_key VARCHAR(64) PRIMARY KEY,setting_value DECIMAL(15,5) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS pricing_tiers (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,threshold_value DECIMAL(15,3) NOT NULL UNIQUE,percent_value DECIMAL(8,3) NOT NULL,sort_order INT UNSIGNED NOT NULL DEFAULT 0,INDEX idx_pricing_sort (sort_order,threshold_value)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS papers (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,paper_type ENUM('ورق','ظرف') NOT NULL,paper_name VARCHAR(255) NOT NULL UNIQUE,available TINYINT(1) NOT NULL DEFAULT 0,price DECIMAL(15,3) NOT NULL DEFAULT 0,sheet_size VARCHAR(32) NOT NULL,sheets_per_pack INT UNSIGNED NOT NULL DEFAULT 0,a3_count INT UNSIGNED NOT NULL DEFAULT 0,a4_count INT UNSIGNED NOT NULL DEFAULT 0,a5_count INT UNSIGNED NOT NULL DEFAULT 0,a6_count INT UNSIGNED NOT NULL DEFAULT 0,a7_count INT UNSIGNED NOT NULL DEFAULT 0,card_count INT UNSIGNED NOT NULL DEFAULT 0,sort_order INT UNSIGNED NOT NULL DEFAULT 0,INDEX idx_papers_type_available (paper_type,available),INDEX idx_papers_sort (sort_order,paper_name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO settings (setting_key,setting_value) VALUES ('slefanBigMatte',0.25),('slefanBigGlossy',0.3),('invoicePercent',0.2),('letterPercent',0.45),('printPrice',0.12),('cuttingPrice',0.15),('breakingPrice',0.1),('pocketWhitePrice',0.5),('pocketPrintedPrice',1),('vat',0.15),('invoicePaperPrice',150) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value);
